def transform(grid):
    out = [row[:] for row in grid]
    h = len(grid)
    # The nonzero pattern is a horizontal baseline; each marker grows upward.
    for r, row in enumerate(grid):
        if any(v != 0 for v in row):
            base = r
            for c, v in enumerate(row):
                if v in (2, 8):
                    height = 4 if v == 2 else 3
                    top = max(0, base - height)
                    out[top][c] = v
                    for rr in range(top + 1, base):
                        out[rr][c] = 1
            break
    return out
